// Package timeutil defines the service's unified time semantics: every
// timestamp entering or leaving the service is an RFC 3339 string with an
// explicit offset (or Z). It is interpreted to an absolute Unix-nanosecond
// instant, so history-point selection and time-window checks are independent
// of the server's local zone.
package timeutil

import (
	"errors"
	"time"
)

// ErrInvalidTimestamp reports a timestamp the service cannot interpret.
var ErrInvalidTimestamp = errors.New("invalid timestamp")

// Parse interprets at as an absolute RFC 3339 (including fractional seconds)
// instant. Ambiguous and unparseable inputs are rejected.
func Parse(at string) (int64, error) {
	if at == "" {
		return 0, ErrInvalidTimestamp
	}
	parsed, err := time.Parse(time.RFC3339Nano, at)
	if err != nil {
		return 0, ErrInvalidTimestamp
	}
	return parsed.UnixNano(), nil
}

// Format renders a Unix-nanosecond instant back to canonical RFC 3339 UTC.
func Format(nanos int64) string {
	return time.Unix(0, nanos).UTC().Format(time.RFC3339Nano)
}
package api

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/feature-flag-service/internal/store"
	"github.com/luwa07832/feature-flag-service/internal/timeutil"
)

type createKeyRequest struct {
	Key string `json:"key"`
}

type putConfigRequest struct {
	Enabled    bool    `json:"enabled"`
	Percentage int     `json:"percentage"`
	Window     *window `json:"window"`
}

type window struct {
	StartsAt *string `json:"starts_at"`
	EndsAt   *string `json:"ends_at"`
}

func createEnvironment(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		var req createKeyRequest
		if !decodeStrict(c, &req) || !validKey(c, req.Key) {
			return
		}
		env, err := st.CreateEnvironment(req.Key)
		if err != nil {
			writeStoreError(c, err)
			return
		}
		c.JSON(http.StatusCreated, gin.H{
			"key":        env.Key,
			"created_at": timeutil.Format(env.CreatedAt),
		})
	}
}

func putConfig(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		environment := c.Param("environment")
		flagKey := c.Param("flagKey")
		if !validPathKeys(c, environment, flagKey) {
			return
		}
		var req putConfigRequest
		if !decodeStrict(c, &req) {
			return
		}
		if req.Percentage < 0 || req.Percentage > 100 {
			fail(c, http.StatusBadRequest, codeInvalidRequest, "percentage must be between 0 and 100")
			return
		}
		startsAt, endsAt, ok := parseWindow(c, req.Window)
		if !ok {
			return
		}
		if !referencedResourcesExist(c, st, environment, flagKey) {
			return
		}
		record, err := st.PutConfig(store.PutConfigInput{
			FlagKey:     flagKey,
			Environment: environment,
			Enabled:     req.Enabled,
			Percentage:  req.Percentage,
			StartsAt:    startsAt,
			EndsAt:      endsAt,
		})
		if err != nil {
			writeStoreError(c, err)
			return
		}
		c.JSON(http.StatusCreated, configJSON(*record))
	}
}

func deleteConfig(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		environment := c.Param("environment")
		flagKey := c.Param("flagKey")
		if !validPathKeys(c, environment, flagKey) {
			return
		}
		if !referencedResourcesExist(c, st, environment, flagKey) {
			return
		}
		record, err := st.DeleteConfig(flagKey, environment)
