func TestDefinitionHistoryRecordsCreateAndUpdate(t *testing.T) {
	h := newHarness(t)
	created := createFlagFull(t, h,
		`{"key":"checkout","description":"First","labels":["zeta","alpha","alpha"]}`)

	h.setTime("2026-02-01T00:00:00Z")
